import math

# Candidates for m
M = [5, 10, 13, 17, 20, 25, 26, 29, 34, 37]
results = {}

for m in M:
    pairs = []
    # Search for pairs (x, y) such that x^2 + y^2 = m, with 1 <= x < y
    limit = int(math.sqrt(m / 2))
    for x in range(1, limit + 1):
        y_squared = m - x*x
        y = math.isqrt(y_squared)

        if y * y == y_squared and y > x:
            pairs.append((x, y))

    constraints = []
    is_consistent_basic = True # Placeholder for consistency check

    for x, y in pairs:
        # Necessary conditions derived by W1:
        C1 = m
        C2 = (x + y)**2
        C3 = (x - y)**2

        # The minimal constraints R are {C1, C2, C3}
        R = {C1, C2, C3}

        # Consistency Check based on W2: If 1 is required, X must be Z, which likely prevents a complex pair.
        if 1 in R:
            consistency_status = "Inconsistent (Forces X = Z)"
        else:
            consistency_status = "Consistent (No immediate forcing of 1)"

        constraints.append({
            "pair": (x, y),
            "m": m,
            "R": sorted(list(R)),
            "consistency_status": consistency_status
        })

    results[m] = constraints

# Print results in a structured way
print("--- Computational Verification Results ---")
for m in M:
    print(f"\n[Candidate m = {m}]")
    if m in results:
        for res in results[m]:
            print(f"  Pair (x, y): {res['pair']}")
            print(f"    Minimal Constraints R = {res['R']}")
            print(f"    Consistency Check: {res['consistency_status']}")
